import vue from '@vitejs/plugin-vue'
import { defineConfig } from 'vitest/config'

export default defineConfig({
  plugins: [vue()],
  test: {
    environment: 'jsdom',
  },
})

import { flushPromises, mount } from '@vue/test-utils'
import { afterEach, beforeEach, expect, test, vi } from 'vitest'

import SearchPage from './SearchPage.vue'

type DeferredResponse = {
  promise: Promise<Response>
  resolve: (value: Response) => void
}

function deferredResponse(): DeferredResponse {
  let resolve!: (value: Response) => void
  const promise = new Promise<Response>((done) => {
    resolve = done
  })
  return { promise, resolve }
}

function response(name: string, total = 1, price = 1234.5) {
  return new Response(
    JSON.stringify({ items: [{ id: name, name, price }], total }),
    { status: 200, headers: { 'content-type': 'application/json' } },
  )
}

beforeEach(() => {
  history.replaceState(null, '', '/search?q=tea&page=2&locale=fr-FR')
})

afterEach(() => {
  vi.unstubAllGlobals()
  vi.restoreAllMocks()
})

test('hydrates its canonical search state from the URL and formats in that locale', async () => {
  const fetchMock = vi.fn(() => Promise.resolve(response('Thé', 2)))
  vi.stubGlobal('fetch', fetchMock)

  const wrapper = mount(SearchPage)
  await flushPromises()

  expect(wrapper.get('input[name="query"]').element).toHaveProperty('value', 'tea')
  expect(fetchMock).toHaveBeenCalledWith('/api/search?q=tea&page=2', expect.anything())
  expect(wrapper.text()).toContain('2 résultats')
  expect(wrapper.text()).toContain('1 234,50 €')
})

test('writes submissions to history and restores state on back or forward navigation', async () => {
  vi.stubGlobal('fetch', vi.fn(() => Promise.resolve(response('Result'))))
  const pushState = vi.spyOn(history, 'pushState')
  const wrapper = mount(SearchPage)
  await flushPromises()

  await wrapper.get('input[name="query"]').setValue('coffee')
  await wrapper.get('form').trigger('submit')
  await flushPromises()

  expect(pushState).toHaveBeenCalled()
  expect(location.search).toContain('q=coffee')
  expect(location.search).toContain('page=1')

  history.replaceState(null, '', '/search?q=cocoa&page=3&locale=en-US')
  window.dispatchEvent(new PopStateEvent('popstate'))
  await flushPromises()

  expect(wrapper.get('input[name="query"]').element).toHaveProperty('value', 'cocoa')
  expect(fetch).toHaveBeenLastCalledWith('/api/search?q=cocoa&page=3', expect.anything())
})

test('prevents an older request from replacing a newer search result', async () => {
  const first = deferredResponse()
  const second = deferredResponse()
  vi.stubGlobal('fetch', vi.fn().mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise))

  const wrapper = mount(SearchPage)
  await wrapper.get('input[name="query"]').setValue('new')
  await wrapper.get('form').trigger('submit')

  second.resolve(response('Newest'))
  await flushPromises()
  first.resolve(response('Stale'))
  await flushPromises()

  expect(wrapper.text()).toContain('Newest')
  expect(wrapper.text()).not.toContain('Stale')
})

export const supportedLocales = ['en-US', 'fr-FR'] as const
export type SupportedLocale = (typeof supportedLocales)[number]

export type MessageKey =
  | 'title'
  | 'searchLabel'
  | 'searchButton'
  | 'localeLabel'
  | 'previousPage'
  | 'nextPage'
  | 'loading'
  | 'searchError'

type Messages = Record<MessageKey, string> & {
  resultCount: { one: string; other: string }
  pageNumber: string
}

type LocaleConfig = {
  displayName: string
  currency: string
  messages: Messages
}

const localeConfig = {
  'en-US': {
    displayName: 'English (United States)',
    currency: 'USD',
    messages: {
      title: 'Product search',
      searchLabel: 'Search',
      searchButton: 'Search',
      localeLabel: 'Language',
      previousPage: 'Previous page',
      nextPage: 'Next page',
      loading: 'Searching…',
      searchError: 'Search failed',
      resultCount: {
        one: '{count} result',
        other: '{count} results',
      },
      pageNumber: 'Page {page}',
    },
  },
  'fr-FR': {
    displayName: 'Français (France)',
    currency: 'EUR',
    messages: {
      title: 'Recherche de produits',
      searchLabel: 'Rechercher',
      searchButton: 'Rechercher',
      localeLabel: 'Langue',
      previousPage: 'Page précédente',
      nextPage: 'Page suivante',
      loading: 'Recherche en cours…',
      searchError: 'La recherche a échoué',
      resultCount: {
        one: '{count} résultat',
        other: '{count} résultats',
      },
      pageNumber: 'Page {page}',
    },
  },
} satisfies Record<SupportedLocale, LocaleConfig>

export const languageOptions = supportedLocales.map((value) => ({
  value,
  label: localeConfig[value].displayName,
}))

export function isSupportedLocale(value: string | null): value is SupportedLocale {
  return supportedLocales.some((locale) => locale === value)
}

function interpolate(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (placeholder, key: string) => values[key] ?? placeholder)
}

export function createSearchPageFormatter(locale: SupportedLocale) {
  const config = localeConfig[locale]
  const numberFormatter = new Intl.NumberFormat(locale)
  const pluralRules = new Intl.PluralRules(locale)
  const currencyFormatter = new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: config.currency,
  })

  return {
    message(key: MessageKey) {
      return config.messages[key]
    },
    resultCount(count: number) {
      const category = pluralRules.select(count)
      const template = category === 'one'
        ? config.messages.resultCount.one
        : config.messages.resultCount.other

      return interpolate(template, { count: numberFormatter.format(count) })
    },
    pageNumber(page: number) {
      return interpolate(config.messages.pageNumber, { page: numberFormatter.format(page) })
    },
    price(value: number) {
      return currencyFormatter.format(value)
    },
  }
}

import { isSupportedLocale, type SupportedLocale } from './searchPageI18n'

export type SearchState = {
  query: string
  page: number
  locale: SupportedLocale
}

function parsePage(value: string | null): number {
  if (value === null || !/^\d+$/.test(value)) return 1

  const parsed = Number(value)
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : 1
}

export function readSearchState(): SearchState {
  const params = new URLSearchParams(window.location.search)
  const locale = params.get('locale')

  return {
    query: params.get('q') ?? '',
    page: parsePage(params.get('page')),
    locale: isSupportedLocale(locale) ? locale : 'en-US',
  }
}

export function searchStateUrl(state: SearchState): string {
  const params = new URLSearchParams({
    q: state.query,
    page: String(state.page),
    locale: state.locale,
  })

  return `${window.location.pathname}?${params.toString()}${window.location.hash}`
}

